/** Deterministic PDF; optional embedded rectangle glyphs have independently known ink bounds. */
const fixtureFont = "";
export function knownCoordinatePdf(embedded = true): Uint8Array {
    const stream = [
        "BT /F1 20 Tf 1 0 0 1 50 700 Tm (HELLO) Tj",
        "0 -28 Td (Across lines) Tj",
        "0 -28 Td (Second selected line) Tj ET",
        "BT /F1 12 Tf 1 0 0 1 340 700 Tm (Right column) Tj ET",
        "BT /F1 14 Tf 1 0 0 1 50 580 Tm (H) Tj 5 Ts /F1 8 Tf (2) Tj 0 Ts /F1 14 Tf (O) Tj ET",
        "BT /F1 12 Tf 1 0 0 1 50 530 Tm (Dense one) Tj 0 -10 Td (Dense two) Tj ET",
        "BT /F1 16 Tf 1 0 0 1 50 480 Tm [(Fake) -300 (space)] TJ ET"
    ].join("\n");
    const binaryFont = atob(fixtureFont);
    const objects = [
        "<< /Type /Catalog /Pages 2 0 R >>",
        "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 640 860] /CropBox [20 30 620 830] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
        embedded ? `<< /Type /Font /Subtype /TrueType /BaseFont /LabloomFixture /FirstChar 32 /LastChar 126 /Widths [${Array(95).fill(600).join(" ")}] /Encoding /WinAnsiEncoding /FontDescriptor 6 0 R >>` : "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
        "<< /Type /FontDescriptor /FontName /LabloomFixture /Flags 32 /FontBBox [50 0 550 700] /ItalicAngle 0 /Ascent 800 /Descent -200 /CapHeight 700 /StemV 80 /FontFile2 7 0 R >>",
        `<< /Length ${binaryFont.length} /Length1 ${binaryFont.length} >>\nstream\n${binaryFont}\nendstream`
    ];
    let text = "%PDF-1.7\n";
    const offsets = [0];
    objects.forEach((object, index) => {
 offsets.push(text.length); text += `${index + 1} 0 obj\n${object}\nendobj\n`;
});
    const start = text.length;
    text += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
    for (const offset of offsets.slice(1)) text += `${String(offset).padStart(10, "0")} 00000 n \n`;
    text += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;
    return Uint8Array.from(text, letter => letter.charCodeAt(0));
}
/** Fifty lines × sixty printable characters, for genuine pointer/paint feedback tests. */
export function performancePdf(): Uint8Array {
    const line = "Labloom pointer selection feedback test: words across a line. ";
    const text = line.repeat(2).slice(0, 60);
    const stream = Array.from({ length: 50 }, (_, index) => `BT /F1 8 Tf 1 0 0 1 40 ${800 - index * 14} Tm (${text}) Tj ET`).join("\n");
    const objects = [
        "<< /Type /Catalog /Pages 2 0 R >>",
        "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 840] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`
    ];
    let pdf = "%PDF-1.7\n";
    const offsets = [0];
    objects.forEach((object, index) => {
        offsets.push(pdf.length); pdf += `${index + 1} 0 obj\n${object}\nendobj\n`;
    });
    const start = pdf.length;
    pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
    for (const offset of offsets.slice(1)) pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
    pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;
    return new TextEncoder().encode(pdf);
}